  "description": "Wyatt demands answers from Dixie about a dangerous plan; a flashback reveals her ruthless past during a convenience store robbery in 2015, where she abandoned her best friend to escape with the cash.",
  "duration": 100,
  "mode": "M1",
  "aspectRatio": "9:16",
  "directorNotes": {
    "goal": "Establish Dixie as a character capable of cold, calculated betrayal. The present-day tension in the kitchen should feel like a ticking bomb; the flashback should feel like raw, adolescent adrenaline and moral collapse. The final sip of beer is the tell—she has done this before, and she will do it again.",
    "styleGuide": "Present scenes (56, 59): M1 — teal-amber, handheld with operator breath, 35mm grain. Flashback (57, 58): M3 — gritty, high-grain, slight desaturation with blown-out neon, 24fps, harsh shadows. Diegetic audio only. No score. Dialogue drives tension.",
    "warnings": [
      "Flashback contains armed robbery and abandonment of a minor. Intense peer betrayal.",
      "Micro-expressions critical—Dixie's flat affect in kitchen contrasts with frantic energy in flashback.",
      "Police sirens and screaming in flashback must feel chaotic and real, not cinematic."
    ]
  },
  "scenes": [
    {
      "scriptNumber": 56,
      "scriptLocation": "INT. WYATT'S KITCHEN — DAY",
      "title": "Wyatt's Desperation",
      "description": "Wyatt paces frantically across the kitchen, confronting Dixie about a dangerous plan. His desperation peaks as he demands to know what she knows.",
      "duration": 15,
      "start": 0,
      "end": 15,
      "sceneType": "present",
      "mode": "M1",
      "continuity": {
        "location": "INT. WYATT'S KITCHEN — DAY",
        "locationChange": false,
        "timeContinuity": "N/A — first scene",
        "charactersPresent": ["Wyatt", "Dixie"],
        "emotionalCarryover": "N/A — cold open",
        "physicalCarryover": "N/A — cold open",
        "wardrobeCarryover": "N/A — cold open",
        "notes": ["Episode cold open. Wyatt in rumpled shirt, unshaven. Dixie seated, unmoved."]
      },
      "references": [
        { "slot": "[Image1]", "assetId": "wyatt", "type": "character" },
        { "slot": "[Image2]", "assetId": "dixie_adult", "type": "character" },
        { "slot": "[Image5]", "assetId": "kitchen_plate", "type": "environment" }
      ],
      "shots": [
        {
          "id": "56A",
          "title": "Wyatt paces, escalating",
          "description": "Wyatt power-walks back and forth across the kitchen, chopping the air with both hands, shirt half-untucked. His voice rises as he lists the stakes.",
          "duration": 8,
          "start": 0,
          "end": 8,
          "camera": {
            "lens": "40mm",
            "framing": "Wide handheld pan, following subject",
            "movement": "Handheld operator pan, tracking Wyatt left-to-right then right-to-left",
            "fps": 24,
            "shutter": "180 degree",
            "aspectRatio": "9:16"
          },
          "composition": {
            "frameMap": "Kitchen occupies full frame. Wyatt dominates left-to-center, moving. Dixie seated right-background third, soft focus. Negative space ahead of Wyatt's direction of travel.",
            "subjectLock": "[Image1] sweating at temples, jaw clenched, mouth tight. Shirt partially untucked from friction of pacing. [Image2] completely static, eyes level, no micro-movement.",
            "crossFrameRules": "Single on [Image1] with [Image2] deep background. No crossing. Wyatt stays in foreground plane.",
            "focus": "Sharp on [Image1] face and torso. [Image2] soft but readable.",
            "depth": "Shallow DOF, kitchen surfaces sharp"
          },
          "blocking": {
            "location": "Kitchen — central path between table and stove",
            "movement": "[Image1] paces in tight figure-eight, L-R-L-R, hands cutting air on each beat. Both feet planted and driven by core rotation, not floating. Chopping gestures synchronized to verbal stress.",
            "interaction": "[Image1] performing outburst directly at [Image2], though not maintaining eye contact initially",
            "positions": [
              { "subjectId": "[Image1]", "description": "Foreground center, standing, in motion, leaning forward slightly" },
              { "subjectId": "[Image2]", "description": "Right third x=70%, midground seated, back against chair, motionless" }
            ]
          },
          "acting": {
            "emotion": "Escalating anxiety, desperation to provoke a response",
            "verb": "TO PROVOKE — Wyatt is trying to crack Dixie's composure by raising the stakes verbally and physically",
            "bodyLanguage": "[Image1]: Brows pulled down and together, eyes narrowed in frustration. Lower lip tucked inward, jaw muscles visibly clenched. Shoulders hunched upward with tension. Hands chopping in sharp, controlled motions—not wild, but precise and aggressive. Feet planted and pushing hard against the tile. [Image2]: Zero facial change. Eyes tracking Wyatt with zero blink. Lips neutral, unparted. Shoulders completely relaxed against chair back.",
            "dialogue": "\"If it were that simple, why haven't you done it before? We're talking about going to jail, or even dying if things go south!!!\"",
            "microExpressions": [
              "[Image1] (2s mark): Rapid bilateral eye dart down and to the left, then back to Dixie. Reads as internal calculation of how to reach her.",
              "[Image1] (5s mark): Subtle asymmetrical nostril flare on the word 'dying.' One millisecond hold of upper lip tension in left corner only."
            ]
          },
          "timeline": {
            "duration": 8,
            "segments": [
              { "start": 0, "end": 3, "label": "Opening volley — rhetorical escalation" },
              { "start": 3, "end": 6, "label": "Desperation peak — 'going to jail or dying'" },
              { "start": 6, "end": 8, "label": "Vocal crescendo and physical plant" }
            ],
            "beats": [
              { "start": 0, "end": 2, "description": "[Image1] begins pacing left, hand up" },
              { "start": 2, "end": 4, "description": "Reverses direction right, delivers 'why haven't you done it'" },
              { "start": 4, "end": 6, "description": "Paces back left, voice rising, 'going to jail or dying'" },
              { "start": 6, "end": 8, "description": "Plants feet center, jaw locked, stares at [Image2]" }
            ]
          },
          "audio": {
            "dialogue": "\"If it were that simple, why haven't you done it before? We're talking about going to jail, or even dying if things go south!!!\"",
            "ambient": ["Kitchen room tone", "Refrigerator compressor hum in background"],
            "sfx": ["Footsteps on tile — rhythmic, deliberate pacing", "Fabric rustle as shirt shifts"],
            "music": false
          },
          "references": [
            { "slot": "[Image1]", "assetId": "wyatt", "type": "character" },
            { "slot": "[Image2]", "assetId": "dixie_adult", "type": "character" },
            { "slot": "[Image5]", "assetId": "kitchen_plate", "type": "environment" }
          ],
          "prompt": {
            "en": "Scene & Mood: A man in a rumpled button-down paces frantically across a small kitchen, hands chopping the air with controlled aggression, jaw locked tight, sweat visible on his temples. He is trying to crack someone's composure by raising the stakes. Tense, lived-in moment—analog warmth, 35mm grain.\n\nFrame Map: Kitchen occupies full depth. Pacing man dominates left-to-center, moving laterally. Woman seated right-background third, soft focus but readable. Negative space ahead of man's forward momentum. Frame-left pathway clear for his footfalls.\n\nLocation & Blocking — [Image5](plate): Small residential kitchen. Cream cabinets, tile counter, modest appliances. Table center-right. Chair against far wall. Pacing man travels between table and stove island on a tight left-right vector. Woman seated at table, back against chair, completely static. Man's gaze flicks down and away during first phrase, then locks forward as tension rises. No eye contact sustained—his eyes are scanning, hers are fixed.\n\nCross-Frame Rules: Single on [Image1] with [Image2] in soft-focus background. Man stays in foreground plane throughout. No position swaps. No crossing center line. Woman remains frame-right and anchored to chair.\n\nMovement: (1) [Image1] paces in tight figure-eight pattern—left foot forward, rotate hips, step right, reverse. Each footfall deliberate and driven from core, not floating. Hands chopping in quarter-second bursts synchronized to verbal stress points (beat 0, 3, 5). Both palms facing downward, fingers slightly spread, wrists locked. On final phrase 'things go south,' both hands plant on table—controlled impact, no slam. Shoulders hunched upward at rest, no drop. (2) Micro-motion: [Image1] temples glisten with fresh perspiration visible at t=2s. Shirt collar rides up slightly from pacing friction. Breath audible, shallow and rapid. [Image1] at t=2s performs rapid bilateral eye dart (two frames) down-left and back to center—internal calculation. [Image1] at t=5s subtle nostril flare on word 'dying'—one side only, held for one frame. (3) Environmental motion: Refrigerator compressor cycles on at t=4s, soft background hum. (4) Camera motion: Handheld operator pan, tracking subject horizontally. No zoom. Operator sways slightly with footsteps, mimicking human observation.\n\nDialogue: \"If it were that simple, why haven't you done it before? We're talking about going to jail, or even dying if things go south!!!\" spoken by [Image1] across 8 seconds, ~1 word per second, building in intensity on final clause.\n\nLast Frame: (t=8s) [Image1] standing center-foreground, feet planted hip-width apart, both hands resting on table surface, jaw clenched, brows lowered and together, staring directly at [Image2] who remains motionless in chair, eyes tracking him with zero blink. Kitchen tiles sharp, cabinets softly rendered. No on-screen text, no captions, no signage typography, no rendered text in the frame.\n\nWorld Plate: Daytime through kitchen window—soft, diffused natural light casting gentle shadows across counter. Color temperature warm-neutral (approx 3500K). Kitchen walls off-white, tile floor neutral gray. Minimal set dressing—salt shaker, water glass on table. Time: mid-morning, kitchen has lived-in but clean quality. No mess, no signs of struggle yet.\n\nSound Bed: Refrigerator compressor hum (continuous, quiet). Tile footsteps (rhythmic, deliberate). Fabric rustle (shirt moving with torso rotation). No dialogue restated here. No music.\n\nCapture Realism: (1) Depth via suspended atmosphere between foreground man and background woman—kitchen air visible as slight haze between planes, creates dimensional separation without being obvious. (2) Moisture without shine: perspiration on temples reads as biological stress, not cosmetic. Fine bead of sweat, no gloss. Upper lip dry. (3) Per-zone speculars: skin receives zero specular reflection—true matte subcutaneous scattering, real peach fuzz visible on jaw, pores evenly textured, no artificial highlight. Ceiling light soft and diffused, not a hot source. (4) Contrast curve: shadows lifted to hold detail in eye sockets and under jaw (no black holes). Highlights rolled on skin to hold pore texture (no blown-out foreheads). Speculars killed entirely—no shine on teeth, lips, or forehead despite perspiration.\n\nCamera Capture: Handheld 35mm anamorphic (2x squeeze, 40mm equivalent), 24fps, 180-degree shutter, Kodak Portra 400 color-negative film stock. Operator-stabilized handheld pan following subject left-right, slight sway with footsteps. No zoom. Teal-amber grade with lifted blacks and rolled highlights. Fine 35mm grain visible in shadows. Frame rate 24fps locked, slight motion blur on hand gestures and footfalls. Total runtime 8 seconds."
          },
          "render": {
            "mode": "M1",
            "engine": "Seedance"
          },
          "notes": {
            "todos": [
              "Load [Image1] Wyatt — sweaty variant, shirt half-untucked",
              "Load [Image5] kitchen_plate — residential, cream cabinets, tile floor",
              "Confirm micro-expression timing: eye dart at t=2s, nostril flare at t=5s"
            ],
            "warnings": [
              "Ensure Wyatt's pacing creates footfall sound sync with dialogue rhythm",
              "Dixie must show ZERO emotion — completely flat face is the tell"
            ],
            "approved": false
          }
        },
        {
          "id": "56B",
          "title": "Wyatt demands the secret",
          "description": "Wyatt stops pacing, turns directly to Dixie, and asks the question that pivots the scene. Dixie stares back unblinking.",
          "duration": 7,
          "start": 8,
          "end": 15,
          "camera": {
            "lens": "55mm",
            "framing": "Close two-shot, Wyatt left, Dixie right",
            "movement": "Static, locked tripod",
            "fps": 24,
            "shutter": "180 degree",
            "aspectRatio": "9:16"
          },
          "composition": {
            "frameMap": "Wyatt left third (x=30%), standing, closer to camera. Dixie right third (x=70%), seated, midground. Both faces visible and readable. Negative space above heads.",
            "subjectLock": "[Image1] jaw still clenched, temples still wet. Eyes now locked on [Image2]. [Image2] completely static, unblinking, eyes level.",
            "crossFrameRules": "Two-shot locked. Wyatt stays left, Dixie stays right. No movement between them. Eyeline: Wyatt looking down-right at Dixie. Dixie looking straight ahead, not tracking Wyatt.",
            "focus": "Sharp on both faces. Kitchen background soft.",
            "depth": "Medium depth of field"
          },
          "blocking": {
            "location": "Kitchen — Wyatt has stopped between table and stove. Dixie seated at table.",
            "movement": "[Image1] pivots hips left, plants both feet, turns head to face [Image2]. Movement takes 1 second, then locked.",
            "interaction": "[Image1] asking a direct question of [Image2], who does not respond physically.",
            "positions": [
              { "subjectId": "[Image1]", "description": "Standing, foreground-left, feet planted, facing [Image2]" },
              { "subjectId": "[Image2]", "description": "Seated at table, midground-right, immobile" }
            ]
          },
          "acting": {
            "emotion": "Desperate need for information, vulnerability beneath the aggression",
            "verb": "TO PLEAD — Wyatt is asking Dixie to give him something he needs to survive this situation",
            "bodyLanguage": "[Image1]: Jaw still clenched, but eyes now softer, showing vulnerability. Brows slightly raised at center, creating two small horizontal lines on forehead. Mouth slightly open, waiting for answer. Shoulders still tense but no longer hunched. Hands hang at sides, fingers slightly curled. Breathing visible in chest. [Image2]: Zero change. Unblinking. No micro-movement. Lips neutral. Eyes not tracking Wyatt—looking slightly past him or at a fixed point.",
            "dialogue": "\"What do you know that I don't?\"",
            "microExpressions": [
              "[Image1] (9s mark): Rapid eye blink (double-blink in quick succession), then 3-second hold without blinking. Shows internal vulnerability.",
              "[Image2] (throughout): Zero eye movement, zero blink. Reads as psychic distance and control."
            ]
          },
          "timeline": {
            "duration": 7,
            "segments": [
              { "start": 8, "end": 9, "label": "Pivot and turn — physical reset" },
              { "start": 9, "end": 12, "label": "Question delivery — measured, lower volume" },
              { "start": 12, "end": 15, "label": "Hold — waiting for answer that won't come" }
            ],
            "beats": [
              { "start": 8, "end": 9, "description": "[Image1] pivots hips and shoulders left, plants feet, head follows" },
              { "start": 9, "end": 12, "description": "[Image1] delivers line 'What do you know that I don't?' in slower, more measured tone" },
              { "start": 12, "end": 15, "description": "[Image1] waits. [Image2] does not answer. Silence holds." }
            ]
          },
          "audio": {
            "dialogue": "\"What do you know that I don't?\" spoken by [Image1] across 3 seconds, slower cadence, vulnerability in tone.",
            "ambient": ["Kitchen room tone", "Refrigerator hum continuing"],
            "sfx": ["Single footstep as [Image1] plants final foot"],
            "music": false
          },
          "references": [
            { "slot": "[Image1]", "assetId": "wyatt", "type": "character" },
            { "slot": "[Image2]", "assetId": "dixie_adult", "type": "character" },
            { "slot": "[Image5]", "assetId": "kitchen_plate", "type": "environment" }
          ],
          "prompt": {
            "en": "Scene & Mood: A man stops mid-stride and turns to face a woman seated at the kitchen table. His question carries desperate vulnerability beneath the surface tension. Analog warmth, teal-amber grade, 35mm grain. Silent moment punctuated by a single question.\n\nFrame Map: Two-shot locked composition. Man left third (x=30%), standing closer to camera, face readable. Woman right third (x=70%), seated, face level and readable, eyes ahead and not tracking man. Negative space above both heads. Kitchen table occupies center-background.\n\nLocation & Blocking — [Image5](plate): Kitchen remains same as previous shot—cream cabinets, tile floor, modest furniture. [Image1] stands between table and stove, having pivoted left 90 degrees. [Image2] remains seated at table, back against chair. No furniture moved. Sightlines: [Image1] is looking down-right at [Image2]'s face. [Image2] is looking straight ahead, eyes at a fixed point, not tracking [Image1].\n\nCross-Frame Rules: Two-shot locked. [Image1] stays left, [Image2] stays right. No movement between them across the cut. Eyeline mismatch intentional—[Image1] seeking connection, [Image2] refusing to give it.\n\nMovement: (1) [Image1] pivots hips and shoulders to face [Image2] over 1 second (t=8s to t=9s). Right foot stays planted, left foot steps inward to hip-width stance. Head follows shoulders, arriving at full face on [Image2] by t=9s. Then locked static. Hands drop to sides, fingers slightly curled. Breathing visible in upper chest and shoulders. (2) Micro-motion: [Image1] at t=9s performs rapid double-blink (two frames), then holds eyes open without blinking for 3 full seconds. Vulnerability blink. [Image2] zero eye movement throughout. No blink. Eyes fixed. (3) Environmental motion: Refrigerator continues hum, no change. (4) Camera: Locked tripod, no movement.\n\nDialogue: \"What do you know that I don't?\" spoken by [Image1] across 3 seconds (t=9s to t=12s), measured cadence, slower than previous outburst, seeking rather than demanding.\n\nLast Frame: (t=15s) Two-shot held. [Image1] standing left, jaw slightly less clenched, brows raised at center creating faint forehead lines, eyes open and vulnerable, mouth slightly parted. [Image2] seated right, completely motionless, unblinking, eyes fixed ahead or slightly past [Image1]. Kitchen tiles sharp in foreground, cabinets soft. No on-screen text, no captions, no signage typography, no rendered text in the frame.\n\nWorld Plate: Same kitchen interior. Daytime natural light continues from window off-frame. Warm-neutral color temperature. Shadows cast by window frame visible on far wall. Kitchen maintains lived-in, clean quality. No change in atmospheric conditions.\n\nSound Bed: Refrigerator compressor hum (continuous, subtle). Single footstep at t=9s (left foot planting). Ambient kitchen silence otherwise. No dialogue restated here. No music.\n\nCapture Realism: (1) Depth via kitchen air suspended between foreground man and background woman—slight haze visible in two-shot separation. (2) Skin receives zero specular highlight—true matte finish, peach fuzz visible on lower jaw, pores evenly textured on cheeks and forehead. Perspiration from previous scene now cooling but still visible at temples as biological evidence, not shine. (3) Per-zone speculars: eyes receive soft catch light only (no hot sources), lips appear naturally moist without gloss, no shine on teeth. Ceiling light diffused and soft. (4) Contrast curve: shadows lifted in eye sockets and under jaw to hold expression (no black holes obscuring emotion), highlights rolled on skin to preserve pore texture, speculars killed entirely.\n\nCamera Capture: Handheld 35mm anamorphic (2x squeeze, 55mm equivalent), locked tripod, 24fps, 180-degree shutter, Kodak Portra 400 color-negative film stock. No camera movement. Teal-amber grade with lifted blacks and rolled highlights. Fine 35mm grain visible throughout. Frame rate 24fps. Total runtime 7 seconds."
          },
          "render": {
            "mode": "M1",
            "engine": "Seedance"
          },
          "notes": {
            "todos": [
              "Confirm [Image1] vulnerability expression readable in two-shot",
              "Confirm [Image2] complete stillness and unfocused gaze"
            ],
            "warnings": [
              "Dixie's non-response is more powerful than any dialogue. Ensure her face reads as intentionally absent of emotion."
            ],
            "approved": false
          }
        }
      ]
    },
    {
      "scriptNumber": 57,
      "scriptLocation": "INT. CONVENIENCE STORE - NIGHT (FLASHBACK - HALLOWEEN 2015 / DIXIE IS 15)",
      "title": "The Setup — Cheap Masks and Distraction",
      "description": "Inside a convenience store decorated with cheap plastic Halloween decorations. Dixie (15) and Destiny (15) wear plastic cat masks and wait for the signal. A young clerk is distracted by a car magazine. The moment the robbers burst through the door with a gun, the girls move with synchronized precision to steal from the register.",
      "duration": 32,
      "start": 15,
      "end": 47,
      "sceneType": "flashback",
      "mode": "M3",
      "continuity": {
        "location": "INT. CONVENIENCE STORE - NIGHT (FLASHBACK)",
        "locationChange": true,
        "timeContinuity": "SMASH CUT to Halloween night 2015, 8 years earlier. Night, interior, completely different space from kitchen.",
        "charactersPresent": ["Dixie (15)", "Destiny (15)", "Young Clerk", "Two Monster-Masked Robbers"],
        "emotionalCarryover": "N/A — flashback break. Emotional tone shifts from contained desperation to frantic adrenaline.",
        "physicalCarryover": "N/A — different timeline. Dixie is 15 years old, moving with teenage agility.",
        "wardrobeCarryover": "N/A — Halloween costume: plastic cat mask, casual teen clothing appropriate to 2015.",
        "notes": [
          "SMASH CUT TO — visual and tonal break from present-day kitchen.",
          "M3 mode: gritty, high-grain, slight desaturation with blown-out orange neon.",
          "This is the origin story of Dixie's ruthlessness. Every action is synchronized, no hesitation.",
          "Cheap plastic pumpkins and orange neon lights create unreal, eerie atmosphere."
        ]
      },
      "references": [
        { "slot": "[Image3]", "assetId": "dixie_15", "type": "character" },
        { "slot": "[Image4]", "assetId": "destiny_15", "type": "character" },
        { "slot": "[Image6]", "assetId": "convenience_store_plate", "type": "environment" }
      ],
      "shots": [
        {
          "id": "57A",
          "title": "Dixie and Destiny wait — masked, watching",
          "description": "Dixie in plastic cat mask stares directly into camera, motionless. Destiny mirrors her posture across the aisle. A young clerk with an oversized mullet is buried in a car magazine. Orange neon light fills the store. They are waiting.",
          "duration": 9,
          "start": 15,
          "end": 24,
          "camera": {
            "lens": "40mm",
            "framing": "Static wide shot of convenience store floor",
            "movement": "Locked off, slight tremor (handheld lockoff)",
            "fps": 24,
            "shutter": "180 degree",
            "aspectRatio": "9:16"
          },
          "composition": {
            "frameMap": "Convenience store floor plan: shelves stage-left, register and counter center-back, aisle center-frame. Dixie left-center foreground wearing plastic cat mask, motionless. Destiny right side of aisle midground, same mask. Clerk center-back at register, head down in magazine. Plastic orange pumpkin decorations scattered throughout foreground and shelves. Neon orange glow fills entire frame.",
            "subjectLock": "[Image3] completely static in plastic cat mask. Face obscured by mask eyeholes, but eye contact straight into camera evident. [Image4] mirrored on opposite side, same stillness. Clerk in background, completely oblivious.",
            "crossFrameRules": "Static wide shot. Three separate spatial zones: Dixie foreground-left, Destiny foreground-right, Clerk background-center. All three held static.",
            "focus": "Shallow—sharp on Dixie and Destiny masks, clerk soft in background.",
            "depth": "Deep space, shelves and counter visible background"
