            "interaction": "Silent communication between [Image3] and [Image4] via eye contact through mask eyeholes. Watching clerk. No physical contact.",
            "positions": [
              { "subjectId": "[Image3]", "description": "Standing left-center aisle, facing camera, plastic cat mask on, hands at sides, completely motionless" },
              { "subjectId": "[Image4]", "description": "Standing right-center aisle, mirrored position, same mask, same stillness" },
