            ]
          },
          "timeline": {
            "duration": 9,
            "segments": [
              { "start": 15, "end": 18, "label": "Establishing the wait — all three subjects in position" },
              { "start": 18, "end": 21, "label": "Silent synchronization check — girls eye-dart in unison" },
              { "start": 21, "end": 24, "label": "Hold — waiting for the door" }
            ],
            "beats": [
