              { "start": 18, "end": 19, "description": "[Image3] eye-dart to [Image4], quick coordination check" },
              { "start": 19, "end": 20, "description": "[Image4] mirrors the dart back" },
              { "start": 20, "end": 24, "description": "Both return to forward stillness. Waiting. Tension builds silently." }
            ]
          },
          "audio": {
