            "ambient": [
              "Convenience store fluorescent hum (low frequency)",
              "Orange neon sign buzz (higher frequency, slightly irregular)",
              "Faint sound of magazine pages turning (clerk, distant, muffled)"
            ],
            "sfx": ["None"],
            "music": false
          },
          "references": [
            { "slot": "[Image3]", "assetId": "dixie_15", "type": "character" },
            { "slot": "[Image4]", "assetId": "destiny_15", "type": "character" },
            { "slot": "[Image6]", "assetId": "convenience_store_plate", "type": "environment" }
